package dev.veltraph.client.navigation;

import dev.veltraph.client.world.*;
import org.junit.jupiter.api.Test;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;

/** Original private fixture cubes plus actual C course/partial-foot pose. Pure policy replay, not native acceptance. */
class BottleCollarLevelRouteTest {
    static final Vec3 START=new Vec3(15.353255455143547,70,.9834704129475308),GOAL=new Vec3(21.5,70,1.5),PARTIAL=new Vec3(17.156559781928657,71,1.7083378395229005);
    static final class Collar implements GroundPathfinder.Terrain {
        final Map<BlockPos,String> changes=new HashMap<>();
        String block(BlockPos p){if(changes.containsKey(p))return changes.get(p);if(p.x()< -4||p.x()>48||p.z()< -5||p.z()>5||p.y()<69||p.y()>74)return "unloaded";if(p.y()==69)return "stone";if(p.y()==70){if((p.x()==16||p.x()==18)&&p.z()==0||p.x()==17&&Math.abs(p.z())==1)return "stone";if(p.x()==17&&p.z()==0)return "water";if(p.z()==2&&p.x()>=21&&p.x()<=43&&p.x()%2==1)return "chest";}return "air";}
        public boolean clear(BlockPos p){return block(p).equals("air");}public boolean floor(BlockPos p){return block(p).equals("stone");}
        double height(double x,int ceiling,double z){double top=Double.NaN;for(double dx:new double[]{-.3,.3})for(double dz:new double[]{-.3,.3}){var b=new BlockPos((int)Math.floor(x+dx),ceiling-1,(int)Math.floor(z+dz));String kind=block(b);double h=kind.equals("stone")?b.y()+1:kind.equals("chest")&&x+dx-b.x()>=.0625&&x+dx-b.x()<=.9375&&z+dz-b.z()>=.0625&&z+dz-b.z()<=.9375?b.y()+.875:Double.NaN;if(!Double.isFinite(h)||Double.isFinite(top)&&Math.abs(top-h)>.6)return Double.NaN;top=Double.isFinite(top)?Math.max(top,h):h;}return top;}
        boolean body(Vec3 p){for(int x=(int)Math.floor(p.x()-.3);x<=Math.floor(p.x()+.3);x++)for(int y=(int)Math.floor(p.y()+.001);y<=Math.floor(p.y()+1.7999999523162842);y++)for(int z=(int)Math.floor(p.z()-.3);z<=Math.floor(p.z()+.3);z++){var q=new BlockPos(x,y,z);String b=block(q);if(b.equals("water")||b.equals("unloaded"))return false;if(b.equals("stone"))return false;if(b.equals("chest")&&p.x()+.3>x+.0625&&p.x()-.3<x+.9375&&p.z()+.3>z+.0625&&p.z()-.3<z+.9375&&p.y()+.001<y+.875)return false;}return true;}
        public Vec3 position(BlockPos p){double h=height(p.x()+.5,p.y(),p.z()+.5);return new Vec3(p.x()+.5,Double.isFinite(h)?h:p.y(),p.z()+.5);}
        public Vec3 surfacePosition(Vec3 p){double h=height(p.x(),GroundPathfinder.node(p).y(),p.z());return Double.isFinite(h)?new Vec3(p.x(),h,p.z()):p;}
        public boolean standable(BlockPos p){var v=position(p);return Double.isFinite(height(v.x(),p.y(),v.z()))&&body(v);}
        public boolean standingClear(Vec3 p){double h=height(p.x(),GroundPathfinder.node(p).y(),p.z());return Double.isFinite(h)&&Math.abs(h-p.y())<.08&&body(p);}
        boolean sweep(Vec3 a,Vec3 b){int n=Math.max(1,(int)Math.ceil(a.distanceTo(b)*10));for(int i=0;i<=n;i++)if(!body(TravelPath.lerp(a,b,i/(double)n)))return false;return true;}
        public boolean walkClear(Vec3 a,Vec3 b){if(Math.abs(a.y()-b.y())>.6)return false;int n=Math.max(1,(int)Math.ceil(a.distanceTo(b)*10));double last=a.y();for(int i=0;i<=n;i++){var p=TravelPath.lerp(a,b,i/(double)n);double h=height(p.x(),GroundPathfinder.node(p).y(),p.z());if(!Double.isFinite(h)||Math.abs(h-last)>.6||Math.abs(h-p.y())>.6||!body(new Vec3(p.x(),h,p.z())))return false;last=h;}return Math.abs(last-b.y())<.08;}
        public boolean stepClear(Vec3 a,Vec3 b){if(walkClear(a,b))return true;double dy=b.y()-a.y();if(Math.abs(dy)>1.001||!body(a)||!body(b))return false;if(dy>.6){var upA=new Vec3(a.x(),a.y()+1.25,a.z());var upB=new Vec3(b.x(),a.y()+1.25,b.z());return sweep(a,upA)&&sweep(upA,upB)&&sweep(upB,b);}if(dy<-.6){var ledge=new Vec3(b.x(),a.y(),b.z());return sweep(a,ledge)&&sweep(ledge,b);}return false;}
    }
    static GroundPathfinder.Result preferred(Collar t,BlockPos start,BlockPos goal,int budget,int radius){return GroundPathfinder.findLevelFirst(t,start,goal,budget,radius);}
    @Test void historicalMeasuredCollarJumpStillBlocksPartialFoot(){var t=new Collar();// Preserve the old native cardinal course exactly as a physical regression. The new
        // diagonal planner is allowed to choose a safer level path instead of this jump.
        var path=new GroundPathfinder.Result(List.of(new BlockPos(15,70,1),new BlockPos(16,70,1),new BlockPos(17,71,1),new BlockPos(18,70,1),new BlockPos(19,70,1),new BlockPos(20,70,1),new BlockPos(21,70,1)),"",0);var walker=new WalkController(()->1L);walker.start(path.steps(),GOAL,0);var out=walker.tick(new WalkController.Input(START,254.53f,true,0),t,4000);assertEquals(WalkController.State.WALKING,out.state());for(Vec3 p:List.of(new Vec3(15.5,70,1.5),new Vec3(16.5,70,1.5))){out=walker.tick(new WalkController.Input(p,270,true,50),t,4000);assertEquals(WalkController.State.WALKING,out.state(),walker.diagnostics());}assertTrue(walker.diagnostics().contains("index=2"),walker.diagnostics());assertTrue(t.body(PARTIAL));assertTrue(Double.isNaN(t.height(PARTIAL.x(),71,PARTIAL.z())));assertFalse(t.standingClear(PARTIAL));var target=new Vec3(17.5,71,1.5);assertTrue(t.standingClear(target));assertFalse(t.walkClear(PARTIAL,target));assertFalse(t.stepClear(PARTIAL,target));assertFalse(GroundPathfinder.canStep(t,GroundPathfinder.node(PARTIAL),GroundPathfinder.node(target)));out=walker.tick(new WalkController.Input(PARTIAL,254.41711f,true,150),t,4000);assertEquals(WalkController.State.BLOCKED,out.state());assertTrue(walker.diagnostics().contains("edge obstruction"));assertFalse(out.forward()||out.jump());}
    @Test void callerPreferenceUsesReachableLevelRouteWithoutRemovingCollarOrWeakeningWalker(){var t=new Collar();var path=preferred(t,GroundPathfinder.node(START),GroundPathfinder.node(GOAL),2500,32);assertTrue(path.found(),path.reason());assertTrue(path.steps().stream().allMatch(p->p.y()==70),path.steps().toString());assertEquals("stone",t.block(new BlockPos(17,70,1)));assertEquals("water",t.block(new BlockPos(17,70,0)));var previous=GroundPathfinder.node(START);for(var p:path.steps()){assertTrue(GroundPathfinder.canStep(t,previous,p));previous=p;}var walker=new WalkController(()->1L);walker.start(path.steps(),GOAL,0);var out=walker.tick(new WalkController.Input(START,254.53f,true,0),t,4000);assertEquals(WalkController.State.WALKING,out.state());assertFalse(out.jump());long time=50;for(var p:path.steps()){out=walker.tick(new WalkController.Input(t.position(p),out.yaw(),true,time),t,4000);time+=50;assertNotEquals(WalkController.State.BLOCKED,out.state(),walker.diagnostics());assertFalse(out.jump());}for(int i=0;i<30&&out.state()!=WalkController.State.ARRIVED;i++){out=walker.tick(new WalkController.Input(GOAL,out.yaw(),true,time),t,4000);time+=50;}assertEquals(WalkController.State.ARRIVED,out.state());assertTrue(path.visited()<=2500);}
    @Test void noLevelRouteFallsBackWithinTheOriginalTotalSearchBudget(){var t=new Collar();for(int x=-4;x<=48;x++)for(int z:new int[]{-2,2})t.changes.put(new BlockPos(x,70,z),"stone");var result=preferred(t,GroundPathfinder.node(START),GroundPathfinder.node(GOAL),2500,32);assertTrue(result.found(),result.reason());assertTrue(result.steps().stream().anyMatch(p->p.y()==71));assertTrue(result.visited()<=2500);}
    @Test void unsupportedGoalAndUnsafeBodyRemainRefused(){for(int variant=0;variant<2;variant++){var t=new Collar();if(variant==0)t.changes.put(new BlockPos(21,69,1),"air");else t.changes.put(new BlockPos(21,71,1),"stone");var r=preferred(t,GroundPathfinder.node(START),GroundPathfinder.node(GOAL),2500,32);assertFalse(r.found());assertTrue(r.visited()<=2500);}}
    @Test void tinyBudgetIsSharedRatherThanRenewedForFallback(){var t=new Collar();var r=preferred(t,GroundPathfinder.node(START),GroundPathfinder.node(GOAL),3,32);assertFalse(r.found());assertTrue(r.visited()<=3);}
    @Test void differingGoalHeightKeepsTheOrdinaryGuardedPlanner(){var t=new Collar();var start=GroundPathfinder.node(START);var goal=new BlockPos(17,71,1);assertEquals(GroundPathfinder.find(t,start,goal,2500,32),preferred(t,start,goal,2500,32));}
}
